function compile(expr, instructions = []) {
  if (typeof expr === 'number') {
    instructions.push({ op: 'push', value: expr });
    return instructions;
  }
  const [op, left, right] = expr;
  compile(left, instructions);
  compile(right, instructions);
  instructions.push({ op });
  return instructions;
}

function run(instructions) {
  const stack = [];
  for (const instr of instructions) {
    if (instr.op === 'push') stack.push(instr.value);
    else {
      const b = stack.pop();
      const a = stack.pop();
      stack.push(instr.op === '+' ? a + b : a * b);
    }
  }
  return stack.pop();
}

function compileAdd(leftExpr, rightExpr) {
  const leftInstructions = compile(leftExpr);
  const rightInstructions = compile(rightExpr);
  return [...leftInstructions, ...rightInstructions, { op: '+' }];
}

const instructions = compileAdd(['*', 2, 3], ['*', 4, 5]);
console.log(run(instructions));

